from taf.collectors.simple.factory import SimpleCollectorFactory
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class simple(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_simple_collector(
            self,
            name,
            dir_path,
            file_pattern=None,
            options=None,
            executor=None,
            target_file_name=None,
            sudo_password=None):
        """
        Create Simple Collector from given configuration, it's used to collect files from a remote or local source
        directory to a local target directory.

        :param str name: name (str) - name of collector
        :param str dir_path: dir_path (str) - path of directory of local or remote source directory
        :param str file_pattern: file_pattern (str) - (optional) regular expression file name pattern to match file
        :param str options: options (str) - (optional) options of find command
        :param dict executor: executor (dict) - (optional) setup info host, user, password, port and proxy in dict format for remote execution
                    if set the value to None, it will use a local executor / execute locally.
        :param str target_file_name: target_file_name (str) - (optional) target file name in local target directory
        :param str sudo_password: sudo_password (str) - (optional) sudo password for executing some command which need root right.
        """

        configuration = {'name': name, 'dir_path': dir_path}
        if sudo_password is not None:
            configuration["sudo_password"] = sudo_password
        if executor is not None:
            configuration["executor"] = executor
        if file_pattern is not None:
            configuration["file_pattern"] = file_pattern
        if options is not None:
            configuration["options"] = options
        if target_file_name is not None:
            configuration["target_file_name"] = target_file_name
        logger.info("Creating Simple Collector with alias name " + name)
        simple_collector = SimpleCollectorFactory().create(configuration=configuration, existing_arguments={})
        logger.info("Simple Collector created successfully")
        self.set_alias(name, simple_collector)
